suggestions.before:
const {
  fuzzy: fuzzyWeight = defaultSearchOptions.weights.fuzzy,
  prefix: prefixWeight = defaultSearchOptions.weights.prefix
} = weights || {}

suggestions.after:
const { fuzzyWeight, prefixWeight } = this.mergeWeights(weights)

private mergeWeights(userWeights?: Partial<{ fuzzy: number, prefix: number }>) {
  return {
    fuzzyWeight: userWeights?.fuzzy ?? this._options.searchOptions.weights.fuzzy,
    prefixWeight: userWeights?.prefix ?? this._options.searchOptions.weights.prefix
  }
}
